"""nl — sira_c."""

T = {
"sira_151": ("Welke oom van de Profeet ﷺ aanvaardde de islam en werd een van zijn standvastigste verdedigers in Mekka?", ["Hamza ibn 'Abd al-Muttalib", "Abu Lahab", "Abu Talib", "Al-'Abbas"], "Hamza, de oom en zoogbroeder van de Profeet ﷺ, aanvaardde de islam in Mekka en werd «de leeuw van Allah» genoemd."),
"sira_152": ("In wiens huis kwamen de eerste moslims in Mekka in het geheim bijeen?", ["Het huis van al-Arqam", "Het huis van Abu Bakr", "Het huis van Khadija", "Het huis van Abu Talib"], "Het huis van al-Arqam ibn Abi al-Arqam, op de heuvel Safa, was de eerste plaats van samenkomst en onderricht."),
"sira_153": ("Welke metgezel, die in Mekka de islam aanvaardde, werd later als eerste leraar naar Yathrib gezonden?", ["Mus'ab ibn 'Umayr", "Bilal ibn Rabah", "Khalid ibn al-Walid", "Abu Hurayra"], "Mus'ab ibn 'Umayr, een jonge Mekkaan van voorname familie, werd na de eed van 'Aqabah naar Yathrib gezonden om de Koran te onderwijzen."),
"sira_154": ("Met welk bevel opent soera Al-Muddaththir, waarmee de openbare oproep begon?", ["«O jij die je bedekt! Sta op en waarschuw»", "«Lees, in de naam van je Heer»", "«Bestrijd de ongelovigen»", "«Emigreer naar Medina»"], "«O jij die je met een kleed bedekt! Sta op en waarschuw.»"),
"sira_155": ("Welk vers gebood de Profeet ﷺ openlijk te verkondigen wat hem bevolen was?", ["«Verkondig dus openlijk wat jou bevolen is»", "«Wees geduldig»", "«Reciteer in het geheim»", "«Trek je terug»"], "«Verkondig dus openlijk wat jou bevolen is en wend je af van de veelgodendienaars.»"),
"sira_156": ("Waar hing Quraysh het document van de boycot tegen Banu Hashim op?", ["Binnen in de Ka'ba", "Op de stadspoort", "Op de markt van 'Ukaz", "Op de heuvel Safa"], "De tekst van de boycot werd binnen in de Ka'ba opgehangen, totdat het pact verbroken werd en het document werd opgegeven."),
"sira_157": ("In wiens tuin in Ta'if zocht de Profeet ﷺ beschutting en ontving hij een tros druiven nadat hij verjaagd was?", ["De tuin van 'Utba en Shayba, waar de slaaf 'Addas hem bediende", "Het huis van het opperhoofd van Ta'if", "Een voorbijtrekkende karavaan", "Het huis van een smid"], "Gewond en uit Ta'if verjaagd zocht hij beschutting in een tuin, waar hem druiven werden aangeboden, gebracht door een christelijke slaaf genaamd 'Addas."),
"sira_158": ("Welke metgezel, eerst een felle tegenstander, aanvaardde de islam en kreeg de naam «hij die waarheid van valsheid onderscheidt»?", ["'Umar ibn al-Khattab", "Abu Sufyan", "Khalid ibn al-Walid", "'Amr ibn al-'As"], "'Umar ibn al-Khattab, aanvankelijk vijandig, aanvaardde de islam in Mekka en kreeg de titel al-Faruq."),
"sira_159": ("Bij welke familie verbleef de Profeet ﷺ bij aankomst in Medina, waar zijn kameel neerknielde?", ["Bij Abu Ayyub al-Ansari", "Bij Sa'd ibn Mu'adh", "Bij Ubayy ibn Ka'b", "Bij Anas ibn Malik"], "De kameel knielde neer bij het huis van Abu Ayyub al-Ansari, die de Profeet ﷺ bij zijn aankomst ontving."),
"sira_160": ("Hoe heet de begraafplaats van Medina, waar veel metgezellen begraven liggen?", ["Al-Baqi'", "Al-Mu'alla", "Al-Hijr", "Al-Quba"], "Baqi' al-Gharqad, naast de moskee van de Profeet ﷺ, is de begraafplaats van Medina."),
"sira_161": ("Welke moskee beschrijft de Koran als «vanaf de eerste dag op vroomheid gegrondvest»?", ["De moskee van Quba", "De Heilige Moskee", "De Al-Aqsa-moskee", "De moskee van Kufa"], "«Een moskee die vanaf de eerste dag op vroomheid is gegrondvest is waardiger dat jij er in staat.»"),
"sira_162": ("In welke moskee bad de Profeet ﷺ toen het gebod tot verandering van de qibla werd geopenbaard?", ["De moskee van de twee qibla's (Masjid al-Qiblatayn)", "De moskee van Quba", "De Heilige Moskee", "De Al-Aqsa-moskee"], "Het gebod kwam tijdens het gebed; de biddenden wendden zich naar de Ka'ba, vandaar de naam «moskee van de twee qibla's»."),
"sira_163": ("Welke verplichting werd de moslims in het tweede jaar van de Hidjra voorgeschreven?", ["Het vasten van de maand Ramadan", "De bedevaart", "Het nachtgebed", "De reis naar Ta'if"], "Het vasten van Ramadan werd in Medina verplicht gesteld, in het tweede jaar na de Hidjra."),
"sira_164": ("Welke metgezel zag de woorden van de gebedsoproep in een droom, die de Profeet ﷺ vervolgens overnam?", ["'Abdullah ibn Zayd", "Bilal ibn Rabah", "Abu Bakr", "Mu'adh ibn Jabal"], "'Abdullah ibn Zayd verhaalde de droom van de adhan; de Profeet ﷺ keurde die goed en droeg Bilal op hem te roepen."),
"sira_165": ("Wat zegt de Koran over de handvol stof die de Profeet ﷺ bij Badr wierp?", ["«Jij wierp niet toen je wierp, maar het was Allah die wierp»", "«Je mikte goed»", "«De wind droeg het mee»", "«De engelen wierpen het»"], "«En jij wierp niet toen je wierp, maar het was Allah die wierp.»"),
"sira_166": ("Hoe beschrijft de Koran de toestand van sommige gelovigen toen zij naar Badr vertrokken?", ["Zij twistten erover alsof zij naar de dood gedreven werden", "Zij waren allen vol ijver", "Zij weigerden te gaan", "Zij vroegen uitstel"], "«Zij twistten met jou over de waarheid nadat die duidelijk was geworden, alsof zij naar de dood werden gedreven.»"),
"sira_167": ("Hoe herinnert de Koran de gelovigen aan hun toestand vóór de overwinning?", ["Zij waren weinig in aantal en onderdrukt in het land, toen bood Allah hun onderdak en steunde hen", "Zij waren rijk", "Zij waren talrijk", "Zij heersten al"], "«En gedenk toen jullie weinigen waren en onderdrukt in het land… toen bood Hij jullie onderdak en steunde jullie met Zijn hulp.»"),
"sira_168": ("Welke metgezel stelde bij Badr voor het leger naar de put het dichtst bij de vijand te verplaatsen?", ["Al-Hubab ibn al-Mundhir", "Sa'd ibn Mu'adh", "Al-Miqdad", "Az-Zubayr"], "Al-Hubab ibn al-Mundhir vroeg of de stelling openbaring of mening was; toen hem gezegd werd dat het een mening was, stelde hij voor naar de put op te rukken, en de Profeet ﷺ stemde toe."),
"sira_169": ("Wat was de naam van de waterplaats waar de slag bij Badr plaatsvond?", ["Badr, een put aan de karavaanweg", "Zamzam", "Quba", "Al-Hudaybiyya"], "Badr was een waterplaats aan de karavaanweg tussen Mekka en Syrië; de slag ontleende er haar naam aan."),
"sira_170": ("Welke kwestie over de gevangenen werd na Badr door openbaring behandeld?", ["Het losgeld dat voor de gevangenen werd aanvaard", "De verdeling van het water", "De keuze van het kamp", "De datum van terugkeer"], "De passage spreekt over de gevangenen en het losgeld, en verklaart dan wat genomen werd toegestaan en goed."),
"sira_171": ("Wat keerde volgens soera Al-'Imran de situatie bij Uhud na een aanvankelijk succes?", ["Ongehoorzaamheid en twist over het gegeven bevel", "Het aantal vijanden", "De hitte", "Watergebrek"], "«…totdat jullie de moed verloren en twistten over het bevel en ongehoorzaam waren.»"),
"sira_172": ("Wat zegt de Koran over hen die op de weg van Allah gedood zijn?", ["Denk niet dat zij dood zijn: zij leven bij hun Heer", "Zij slapen tot de Laatste Dag", "Zij keren terug", "Zij zijn vergeten"], "«En denk nooit dat zij die op de weg van Allah gedood zijn dood zijn. Nee, zij leven bij hun Heer en worden voorzien.»"),
"sira_173": ("Op welke heuvel plaatste de Profeet ﷺ de boogschutters bij Uhud?", ["De Heuvel van de Boogschutters (Jabal ar-Rumat)", "De heuvel Safa", "De berg Thawr", "De berg Hira"], "Vijftig boogschutters werden op een heuvel geplaatst die later «de heuvel van de boogschutters» werd genoemd, met het bevel die niet te verlaten."),
"sira_174": ("Hoe beschrijft soera Al-Ahzab de beproeving van het beleg van Medina?", ["De ogen wendden zich af, de harten stegen tot de kelen", "De stad viel", "Alleen het voedsel raakte op", "De hemel verduisterde"], "«Toen zij van boven jullie en van onder jullie op jullie afkwamen, en toen de ogen zich afwendden en de harten tot de kelen stegen.»"),
"sira_175": ("Hoe beschrijft de Koran de afloop van de Slag van de Gracht?", ["Allah dreef de bondgenoten in hun woede terug, zonder dat zij iets goeds hadden bereikt", "Een lange veldslag", "Een vredesverdrag", "Een moslimterugtocht"], "«En Allah dreef hen die ongelovig waren terug in hun woede, zonder dat zij iets goeds hadden bereikt. En Allah was voor de gelovigen voldoende in de strijd.»"),
"sira_176": ("Waar ligt Hudaybiyya, de plaats van het beroemde verdrag?", ["Aan de rand van het heilige gebied, ten westen van Mekka", "Bij Medina", "In Jemen", "In Syrië"], "Hudaybiyya is een plaats aan de rand van het heilige gebied van Mekka, waar het verdrag werd gesloten."),
"sira_177": ("Welk visioen van de Profeet ﷺ bevestigt de Koran na Hudaybiyya?", ["Dat zij de Heilige Moskee veilig zouden binnengaan, met geschoren of geknipt hoofd", "Dat zij bij Khaybar zouden winnen", "Dat zij een stad zouden bouwen", "Dat zij naar Syrië zouden reizen"], "«Voorzeker heeft Allah Zijn Gezant het visioen in waarheid getoond: jullie zullen de Heilige Moskee zeker veilig binnengaan.»"),
"sira_178": ("Wat herinnert soera Al-Fath over de handen die bij Mekka werden weerhouden?", ["Allah weerhield hun handen van jullie en jullie handen van hen binnen Mekka", "Hij beval de strijd", "Hij sloot de wegen af", "Hij zond een storm"], "«En Hij is het die hun handen van jullie weerhield en jullie handen van hen binnen het gebied van Mekka, nadat Hij jullie over hen had doen zegevieren.»"),
"sira_179": ("In welk jaar van de Hidjra vond de expeditie naar Khaybar plaats?", ["Het zevende", "Het tweede", "Het vijfde", "Het tiende"], "Khaybar vond plaats in het jaar 7 na de Hidjra, het jaar na het verdrag van Hudaybiyya."),
"sira_180": ("Hoe heet de 'umrah die het jaar na Hudaybiyya werd verricht, volgens de voorwaarden van het verdrag?", ["'Umrat al-Qada", "Hijjat al-Wada'", "'Umrat al-Ji'ranah", "Al-Hajj al-Akbar"], "Het verdrag bepaalde dat de moslims het volgende jaar zouden terugkeren; die 'umrah heet 'umrat al-qada."),
"sira_181": ("Welke heerser verscheurde de brief van de Profeet ﷺ bij ontvangst?", ["De koning van Perzië (Chosroes)", "De Negus van Abessinië", "De gouverneur van Bahrein", "De koning van Jemen"], "De Profeet ﷺ zond brieven aan de naburige heersers; die aan de koning van Perzië werd verscheurd."),
"sira_182": ("Welke metgezel werd met de brief van de Profeet ﷺ naar de Negus van Abessinië en naar andere heersers gezonden?", ["'Amr ibn Umayya ad-Damri", "Abu Hurayra", "Anas ibn Malik", "Ubayy ibn Ka'b"], "De boodschappers werden uit de metgezellen gekozen; 'Amr ibn Umayya ad-Damri werd naar de Negus gezonden."),
"sira_183": ("In welke richting ligt Khaybar vanuit Medina?", ["Naar het noorden", "Naar het zuiden", "Naar het oosten", "Naar het westen, aan zee"], "Khaybar is een versterkte oase ten noorden van Medina, aan de weg naar Syrië."),
"sira_184": ("Wat werd het huis van Abu Sufyan op de dag dat Mekka werd veroverd?", ["Een plaats van veiligheid voor wie er binnenging", "Een gevangenis", "Een pakhuis", "Een moskee"], "De Profeet ﷺ verklaarde veilig wie de Heilige Moskee binnenging, in zijn eigen huis bleef, of het huis van Abu Sufyan binnenging."),
"sira_185": ("Welk jaar wordt «het jaar van de verovering» ('am al-fath) genoemd?", ["Het jaar 8 na de Hidjra", "Het jaar 6 na de Hidjra", "Het jaar 10 na de Hidjra", "Het jaar 2 na de Hidjra"], "Mekka werd veroverd in het jaar 8 na de Hidjra, het jaar dat bekendstaat als «het jaar van de verovering»."),
"sira_186": ("Welke veldslag volgde kort na de verovering van Mekka, tegen de stammen van Hawazin?", ["Hunayn", "Badr", "Uhud", "Khaybar"], "Hunayn vond kort na de verovering plaats, in een vallei tussen Mekka en Ta'if."),
"sira_187": ("Wat zond Allah neer op Zijn Gezant ﷺ en de gelovigen na hun ontsteltenis bij Hunayn?", ["Zijn rust (sakinah), en troepen die zij niet zagen", "Regen", "Een wind", "Een groep ruiters"], "«Toen zond Allah Zijn rust neer op Zijn Gezant en op de gelovigen en zond troepen neer die jullie niet zagen.»"),
"sira_188": ("Tegen welke stad trok het moslimleger op na Hunayn?", ["Ta'if", "Khaybar", "Tabuk", "Sanaa"], "Na Hunayn belegerden de moslims Ta'if, waarvan de inwoners zich hadden opgesloten."),
"sira_189": ("Welke expeditie noemt de Koran «het uur van moeilijkheid» (sa'at al-'usrah)?", ["Tabuk", "Badr", "Khaybar", "Hunayn"], "«Allah heeft het berouw aanvaard van de Profeet, de uitgewekenen en de helpers die hem volgden in het uur van moeilijkheid.»"),
"sira_190": ("Wat zegt de Koran over de drie metgezellen die bij Tabuk achterbleven, voordat zij vergeven werden?", ["De aarde werd hun te eng ondanks haar wijdheid, toen aanvaardde Allah hun berouw", "Zij werden verbannen", "Zij vertrokken naar Jemen", "Zij werden vergeten"], "«En de drie die achtergelaten werden, totdat de aarde hun te eng werd ondanks haar wijdheid… toen aanvaardde Hij hun berouw.»"),
"sira_191": ("In welke richting ligt Tabuk, het doel van de laatste grote expeditie?", ["Naar het noorden, richting de Syrische grens", "Naar het zuiden, richting Jemen", "Naar het oosten, richting Irak", "Naar het westen, aan de Rode Zee"], "Tabuk ligt ten noorden van Medina, aan de weg naar Syrië; het was de laatste grote expeditie van de Profeet ﷺ."),
"sira_192": ("Welke metgezel rustte een groot deel van het leger van Tabuk uit met zijn eigen vermogen?", ["'Uthman ibn 'Affan", "Sa'd ibn Abi Waqqas", "Talha ibn 'Ubaydillah", "Abu Dharr"], "'Uthman ibn 'Affan leverde een aanzienlijk deel van de uitrusting van «het leger van moeilijkheid» (jaysh al-'usrah)."),
"sira_193": ("Welke metgezel was de eerste die een pijl afschoot op de weg van Allah?", ["Sa'd ibn Abi Waqqas", "Az-Zubayr ibn al-'Awwam", "Talha ibn 'Ubaydillah", "Abu 'Ubayda"], "Sa'd ibn Abi Waqqas, een van de eersten die de islam aanvaardde, staat bekend als de eerste die een pijl afschoot op de weg van Allah."),
"sira_194": ("Welke metgezel wordt «de discipel (hawari) van de Gezant van Allah ﷺ» genoemd?", ["Az-Zubayr ibn al-'Awwam", "Abu Hurayra", "Salman al-Farisi", "Bilal"], "Az-Zubayr ibn al-'Awwam, de neef van de Profeet ﷺ, werd zijn hawari genoemd, zijn naaste steun."),
"sira_195": ("Welke metgezel werd de kennis over de huichelaars toevertrouwd, en werd daarom «de bewaarder van het geheim» genoemd?", ["Hudhayfa ibn al-Yaman", "Abu Musa al-Ash'ari", "'Ammar ibn Yasir", "Abu ad-Darda"], "Hudhayfa ibn al-Yaman staat bekend als «sahib as-sirr», degene aan wie de Profeet ﷺ over de huichelaars vertrouwde."),
"sira_196": ("Waar kwam Salman vandaan, «al-Farisi» genoemd, die de gracht voorstelde?", ["Uit Perzië", "Uit Jemen", "Uit Abessinië", "Uit Byzantium"], "Salman, van Perzische afkomst, zocht lang naar de waarheid voordat hij zich in Medina bij de Profeet ﷺ voegde."),
"sira_197": ("Welke vrouw, de moeder van Anas ibn Malik, bood de Profeet ﷺ de dienst van haar zoon aan?", ["Umm Sulaym", "Umm Salama", "Umm Ayman", "Umm Habiba"], "Umm Sulaym van de Ansar stelde haar zoon Anas aan de Profeet ﷺ voor om hem te dienen toen hij in Medina aankwam."),
"sira_198": ("Welke echtgenote van de Profeet ﷺ stond bekend om haar grote geleerdheid en verhaalde veel hadiths?", ["'Aisha", "Sawda", "Juwayriya", "Maymuna"], "'Aisha, de dochter van Abu Bakr, behoort tot de grootste overleveraars van hadith en is een referentie in religieuze kennis."),
"sira_199": ("Welke echtgenote van de Profeet ﷺ was zijn nicht, en wier huwelijk in soera Al-Ahzab wordt vermeld?", ["Zaynab bint Jahsh", "Hafsa", "Umm Salama", "Safiyya"], "Het huwelijk met Zaynab bint Jahsh wordt vermeld in soera Al-Ahzab (33:37)."),
"sira_200": ("Welke echtgenote van de Profeet ﷺ gaf de raad die de impasse bij Hudaybiyya doorbrak?", ["Umm Salama", "'Aisha", "Hafsa", "Zaynab bint Jahsh"], "Umm Salama raadde de Profeet ﷺ aan zelf naar buiten te gaan en het offer en het scheren te verrichten: de metgezellen volgden onmiddellijk."),
"sira_201": ("Wat is de volledige naam van de Profeet ﷺ, tot zijn grootvader?", ["Muhammad ibn 'Abdillah ibn 'Abd al-Muttalib", "Muhammad ibn Abi Talib", "Muhammad ibn al-'Abbas", "Muhammad ibn Hashim"], "Hij is Mohammed, zoon van 'Abdullah, zoon van 'Abd al-Muttalib, van de stam Quraysh."),
"sira_202": ("Welke andere naam van de Profeet ﷺ, in de Koran genoemd door 'Isa, betekent «meest geprezen»?", ["Ahmad", "Al-Mustafa", "Al-Amin", "Abu-l-Qasim"], "'Isa kondigde een gezant aan die na hem zou komen «wiens naam Ahmad is» (Koran 61:6)."),
"sira_203": ("Over welke periode werd de Koran aan de Profeet ﷺ geopenbaard?", ["Ongeveer drieëntwintig jaar", "Tien jaar", "Veertig jaar", "Eén enkele nacht"], "De openbaring besloeg ongeveer drieëntwintig jaar: dertien in Mekka en tien in Medina."),
"sira_204": ("Welke metgezel was de eerste vrije volwassen man die de islam aanvaardde?", ["Abu Bakr as-Siddiq", "'Umar ibn al-Khattab", "'Uthman ibn 'Affan", "Sa'd ibn Abi Waqqas"], "Onder de vrije volwassen mannen was Abu Bakr de eerste die gehoor gaf aan de oproep van de Profeet ﷺ."),
"sira_205": ("Welk kind was het eerste dat de islam aanvaardde?", ["'Ali ibn Abi Talib", "Anas ibn Malik", "Usama ibn Zayd", "'Abdullah ibn 'Umar"], "'Ali ibn Abi Talib, opgegroeid in het huis van de Profeet ﷺ, was de eerste onder de kinderen die geloofde."),
"sira_206": ("Welke vrijgelatene van de Profeet ﷺ was de eerste onder de vrijgelatenen die de islam aanvaardde?", ["Zayd ibn Haritha", "Bilal ibn Rabah", "Suhayb ar-Rumi", "Salman al-Farisi"], "Zayd ibn Haritha, vrijgelaten en als een zoon opgevoed door de Profeet ﷺ, was de eerste onder de vrijgelatenen die geloofde."),
"sira_207": ("Welk vers beëindigde de wettelijke adoptie, zeggend dat de Profeet ﷺ niet de vader is van een van hun mannen?", ["«Mohammed is niet de vader van een van jullie mannen, maar de Gezant van Allah en het zegel der profeten»", "«Noem hen naar hun vaders»", "«Bloedbanden gaan voor»", "«Adopteer niet»"], "«Mohammed is niet de vader van een van jullie mannen, maar hij is de Gezant van Allah en de laatste der profeten.»"),
"sira_208": ("Op welke dag van de week komen moslims bijeen voor het gemeenschapsgebed dat in Medina werd ingesteld?", ["Vrijdag", "Zaterdag", "Zondag", "Maandag"], "Het vrijdaggebed (al-jumu'ah) werd in Medina ingesteld en brengt de gemeenschap elke week bijeen."),
"sira_209": ("Welke metgezel leidde het gebed tijdens de laatste ziekte van de Profeet ﷺ, op diens eigen bevel?", ["Abu Bakr as-Siddiq", "'Umar ibn al-Khattab", "'Ali ibn Abi Talib", "Bilal"], "De Profeet ﷺ beval dat Abu Bakr tijdens zijn ziekte het gebed zou leiden; de metgezellen zagen dat als een teken."),
"sira_210": ("Welke kalief werd neergestoken terwijl hij het ochtendgebed leidde?", ["'Umar ibn al-Khattab", "Abu Bakr", "'Ali ibn Abi Talib", "Mu'awiya"], "'Umar ibn al-Khattab werd tijdens het fadjr-gebed in Medina neergestoken en stierf aan zijn verwondingen."),
"sira_211": ("Hoe lang duurde het kalifaat van Abu Bakr?", ["Ongeveer twee jaar", "Tien jaar", "Twintig jaar", "Dertig jaar"], "Abu Bakr regeerde ongeveer twee jaar tot zijn dood, en 'Umar volgde hem op."),
"sira_212": ("Tegen welke beweging moest Abu Bakr aan het begin van zijn kalifaat optreden?", ["De weigering van de zakat en de afvalligheid van sommige stammen", "Een invasie uit Perzië", "Een hongersnood", "Een opstand in Medina"], "Het eerste kalifaat begon met de ridda-oorlogen, tegen stammen die de zakat weigerden of de islam verlieten."),
"sira_213": ("Welke titel nam 'Umar ibn al-Khattab aan als hoofd van de gemeenschap?", ["Amir al-Mu'minin (bevelhebber der gelovigen)", "Sultan", "Malik", "Imam al-Haramayn"], "De titel amir al-mu'minin werd onder 'Umar ingesteld en door de kaliefen na hem gedragen."),
"sira_214": ("Welke moskee in Jeruzalem was de eerste qibla van de moslims?", ["De Al-Aqsa-moskee", "De moskee van Quba", "De moskee van de Profeet ﷺ", "De Heilige Moskee"], "De moslims baden eerst richting Jeruzalem, voordat de qibla naar de Ka'ba werd vastgesteld."),
"sira_215": ("Welke drie moskeeën zijn die waarheen reizen in het bijzonder wordt aangemoedigd?", ["De Heilige Moskee, de moskee van de Profeet ﷺ en al-Aqsa", "Quba, al-Aqsa en Kufa", "De Heilige Moskee, Quba en Damascus", "Al-Aqsa, Kufa en Basra"], "Reizen wordt in het bijzonder aangemoedigd naar drie moskeeën: de Heilige Moskee, de moskee van de Profeet ﷺ en de Al-Aqsa-moskee."),
"sira_216": ("Waar hield de Profeet ﷺ zijn afscheidspreek, op de dag van 'Arafah?", ["In de vallei van 'Uranah, bij de berg 'Arafat", "Bij Mina", "Voor de Ka'ba", "Bij Muzdalifah"], "De afscheidspreek werd gehouden op de dag van 'Arafah, in de vallei van 'Uranah aan de voet van de berg 'Arafat."),
"sira_217": ("Wat verklaarde de Profeet ﷺ onschendbaar in zijn afscheidspreek?", ["Ieders bloed, bezit en eer", "De handelsroutes", "De putten van Medina", "De palmgaarden"], "Hij verklaarde het bloed, het bezit en de eer van de moslims heilig, zo heilig als die dag, die maand en die stad."),
"sira_218": ("Wat liet de Profeet ﷺ zijn gemeenschap na in zijn afscheidspreek, opdat zij niet zou dwalen?", ["Het Boek van Allah", "Een schat", "Een leger", "Een kaart"], "Hij herinnerde hen eraan dat hij onder hen achterliet waaraan zij zich moesten vasthouden om niet te dwalen: het Boek van Allah."),
"sira_219": ("Welke maand van de moslimkalender markeert de bedevaart die de Profeet ﷺ bij zijn afscheid verrichtte?", ["Dhul-Hijjah", "Ramadan", "Muharram", "Rajab"], "De afscheidsbedevaart vond plaats in Dhul-Hijjah van het jaar 10 na de Hidjra."),
"sira_220": ("Wie waste en omhulde het lichaam van de Profeet ﷺ na zijn overlijden?", ["De leden van zijn huis, onder wie 'Ali en al-'Abbas", "Alleen de Ansar", "Bilal en Anas", "De mensen van Quba"], "Zijn eigen huisgenoten verzorgden dat, onder wie 'Ali ibn Abi Talib en zijn oom al-'Abbas."),
"sira_221": ("In welke maand van het hidjra-jaar overleed de Profeet ﷺ?", ["Rabi' al-Awwal", "Ramadan", "Shawwal", "Dhul-Qa'dah"], "De Profeet ﷺ overleed in Medina in de maand Rabi' al-Awwal, in het jaar 11 na de Hidjra."),
"sira_222": ("Welk vers reciteerde Abu Bakr om de mensen eraan te herinneren dat de Profeet ﷺ sterfelijk was?", ["«Mohammed is slechts een gezant; vóór hem zijn gezanten heengegaan»", "«Wij zonden jou als een barmhartigheid»", "«Jij bent van een geweldig karakter»", "«Wanneer de hulp van Allah komt»"], "«Mohammed is niet anders dan een gezant. Vóór hem zijn andere gezanten heengegaan. Als hij zou sterven of gedood worden, zouden jullie je dan op je hielen omkeren?»"),
"sira_223": ("Welke metgezel staat vooral bekend om het grote aantal hadiths dat hij uit het hoofd leerde?", ["Abu Hurayra", "Anas ibn Malik", "Jabir ibn 'Abdillah", "Abu Sa'id al-Khudri"], "Abu Hurayra bracht de laatste jaren van de Profeet ﷺ aan diens zijde door en werd de meest productieve overleveraar van hadith."),
"sira_224": ("Welke metgezel, de neef van de Profeet ﷺ, werd de grote autoriteit op het gebied van de Koranexegese?", ["'Abdullah ibn 'Abbas", "'Abdullah ibn 'Umar", "'Abdullah ibn Mas'ud", "'Abdullah ibn az-Zubayr"], "'Abdullah ibn 'Abbas, voor wie de Profeet ﷺ om begrip van het Boek bad, werd «de uitlegger van de Koran»."),
"sira_225": ("Welke metgezel werd door de Profeet ﷺ als gouverneur en rechter naar Jemen gezonden, en stierf jong in Syrië?", ["Mu'adh ibn Jabal", "Abu 'Ubayda ibn al-Jarrah", "'Amr ibn al-'As", "Khalid ibn al-Walid"], "Mu'adh ibn Jabal, een geleerde onder de metgezellen, werd naar Jemen gezonden en stierf later in Syrië, nog jong."),
"sira_226": ("Welke vallei ligt tussen de twee heuvels Safa en Marwa, die tijdens de bedevaart worden belopen?", ["De vallei van Mekka, rond de Ka'ba", "De vallei van 'Uranah", "De vallei van Mina", "De vallei van Badr"], "Safa en Marwa zijn twee kleine heuvels in de vallei van Mekka, tegenwoordig binnen de Heilige Moskee gelegen."),
"sira_227": ("Welke twee grote Arabische stammen van Medina hadden vóór de komst van de Profeet ﷺ oorlog gevoerd?", ["De Aws en de Khazraj", "Quraysh en Hawazin", "Thaqif en Kinana", "Tamim en Bakr"], "De Aws en de Khazraj, lange tijd vijanden, vormden samen de Ansar na de komst van de Profeet ﷺ."),
"sira_228": ("Welk vers herinnert de Ansar eraan dat zij vijanden waren en dat Allah hun harten samenbracht?", ["«Jullie waren vijanden en Hij bracht jullie harten samen»", "«Jullie waren arm»", "«Jullie waren weinigen»", "«Jullie waren verdwaald»"], "«En gedenk de gunst van Allah aan jullie: toen jullie vijanden waren en Hij jullie harten samenbracht, zodat jullie door Zijn gunst broeders werden.»"),
"sira_229": ("Hoe prijst de Koran de Ansar in hun ontvangst van de uitgewekenen?", ["Zij geven anderen de voorkeur boven zichzelf, zelfs in eigen nood", "Zij verkochten hun land", "Zij leenden hun geld", "Zij huisvestten hen buiten de stad"], "«En zij geven anderen de voorkeur boven zichzelf, ook al verkeren zij in behoeftigheid. En wie behoed wordt voor de gierigheid van zijn ziel — zij zijn de welslagenden.»"),
"sira_230": ("Hoe heet het geheel van uitspraken, handelingen en goedkeuringen van de Profeet ﷺ?", ["De Soenna", "De Koran", "De Sira", "De Tafsir"], "De Soenna is wat de Profeet ﷺ zei, deed of goedkeurde; de Sira is het verhaal van zijn leven."),
"sira_231": ("Hoe heet de generatie na die van de metgezellen?", ["De Tabi'un (de volgelingen)", "De Ansar", "De Muhajirun", "De Qurra'"], "De Tabi'un zijn zij die de metgezellen ontmoetten zonder de Profeet ﷺ te hebben gezien."),
"sira_232": ("Hoe heet de keten van overleveraars van een hadith?", ["De isnad", "De matn", "De tafsir", "De tajwid"], "De isnad is de keten van overlevering; de matn is de tekst van de hadith zelf."),
"sira_233": ("Welke twee hadithverzamelingen gelden als de meest strenge, «de twee Sahihs» genoemd?", ["Sahih al-Bukhari en Sahih Muslim", "De Sunan van Abu Dawud en at-Tirmidhi", "De Muwatta' en de Musnad", "De Sunan van an-Nasa'i en Ibn Majah"], "Sahih al-Bukhari en Sahih Muslim worden samen «de twee Sahihs» (as-sahihan) genoemd."),
"sira_234": ("In welke stad bevinden zich de moskee van de Profeet ﷺ en zijn graf?", ["Medina", "Mekka", "Jeruzalem", "Ta'if"], "De moskee van de Profeet ﷺ en zijn graf bevinden zich in Medina, de stad van de Hidjra."),
"sira_235": ("Welke bijnaam draagt Medina, verwijzend naar het licht dat eraan wordt toegeschreven?", ["Al-Madinah al-Munawwarah (de stralende stad)", "Umm al-Qura", "Dar as-Salam", "Al-Mada'in"], "Medina wordt al-Munawwarah genoemd; Mekka wordt van haar kant al-Mukarramah genoemd."),
"sira_236": ("Welke naam geeft de Koran aan Mekka, «de moeder der steden»?", ["Umm al-Qura", "Al-Madinah", "Al-Balad al-Amin", "Bakkah"], "«…opdat jij de moeder der steden (Umm al-Qura) en wie eromheen zijn waarschuwt.»"),
"sira_237": ("Wat was het beroep van de eerste echtgenote van de Profeet ﷺ, Khadija?", ["Koopvrouw", "Geneeskundige", "Dichteres", "Weefster"], "Khadija bint Khuwaylid was een gerespecteerde koopvrouw van Mekka, die haar karavaan aan de jonge Mohammed ﷺ toevertrouwde."),
"sira_238": ("Hoe lang was de Profeet ﷺ alleen met Khadija getrouwd?", ["Tot haar dood; tijdens haar leven huwde hij geen andere vrouw", "Twee jaar", "Vijf jaar", "Hij huwde meteen anderen"], "De Profeet ﷺ huwde geen andere vrouw zolang Khadija leefde; de latere huwelijken kwamen na haar dood."),
"sira_239": ("Wat is de naam van de oom van de Profeet ﷺ die hem beschermde zonder de islam te aanvaarden?", ["Abu Talib", "Hamza", "Al-'Abbas", "Abu Lahab"], "Abu Talib, de vader van 'Ali, beschermde zijn neef tegen Quraysh tot aan zijn dood."),
"sira_240": ("Welke oom van de Profeet ﷺ werd bij Badr gevangengenomen voordat hij de islam aanvaardde?", ["Al-'Abbas ibn 'Abd al-Muttalib", "Abu Talib", "Hamza", "Az-Zubayr ibn 'Abd al-Muttalib"], "Al-'Abbas, de oom van de Profeet ﷺ en stamvader van de Abbasiden, werd bij Badr gevangengenomen en aanvaardde later de islam."),
"sira_241": ("Hoe worden de metgezellen genoemd die bij de slag van Badr vochten?", ["De Badriyyun (de mensen van Badr)", "De Ansar", "De Muhajirun", "De Uhudiyyun"], "De metgezellen die bij Badr aanwezig waren staan bekend als de Badriyyun, en die verdienste is aan hen eigen."),
"sira_242": ("Welk deel van de buit reserveert de Koran voor Allah, de Gezant, de naaste verwanten, de wezen, de armen en de reiziger?", ["Een vijfde", "De helft", "Een tiende", "Een derde"], "«Weet dat van alles wat jullie als buit nemen, een vijfde voor Allah en voor de Gezant is, en voor de naaste verwanten, de wezen, de behoeftigen en de reiziger.»"),
"sira_243": ("Welk vers, vaak samen met de afscheidspreek aangehaald, grondvest de gelijkheid van volkeren voor Allah?", ["«De edelste van jullie bij Allah is de meest godvrezende»", "«De mensen stammen van één vader»", "«Geen ziel draagt de last van een ander»", "«Er is geen dwang in de godsdienst»"], "«O mensen, Wij hebben jullie geschapen uit een man en een vrouw… de edelste van jullie bij Allah is de meest godvrezende.»"),
"sira_244": ("Hoeveel mensen namen deel aan de tweede eed van 'Aqabah, de beslissende ontmoeting met de mensen van Yathrib?", ["Een delegatie van meer dan zeventig personen", "Drie", "Tien", "Vijfhonderd"], "De tweede eed van 'Aqabah bracht een delegatie van meer dan zeventig mannen en vrouwen uit Yathrib bijeen."),
"sira_245": ("Hoeveel naqibs (verantwoordelijke hoofden) liet de Profeet ﷺ bij de eed van 'Aqabah onder de mensen van Yathrib aanstellen?", ["Twaalf", "Vier", "Zeven", "Twintig"], "Twaalf naqibs werden gekozen om de groepen van de delegatie uit Yathrib te vertegenwoordigen en voor hun eed in te staan."),
"sira_246": ("Welke naam kreeg Medina na de Hidjra?", ["Madinat an-Nabi, de stad van de Profeet ﷺ", "Yathrib", "Alleen Taybah", "Al-Qura"], "Yathrib kreeg de naam Madinat an-Nabi, «de stad van de Profeet ﷺ», afgekort tot al-Madinah."),
"sira_247": ("Welke kalief liet officiële afschriften van de Koran maken en naar de provincies zenden?", ["'Uthman ibn 'Affan", "Abu Bakr", "'Umar", "'Ali"], "Abu Bakr liet de tekst verzamelen; 'Uthman liet officiële afschriften maken en naar de belangrijkste steden zenden."),
"sira_248": ("In welke taal werd de Koran aan de Profeet ﷺ geopenbaard?", ["Het Arabisch", "Het Aramees", "Het Perzisch", "Het Grieks"], "De Koran werd geopenbaard in duidelijk Arabisch, de taal van het eigen volk van de Profeet ﷺ."),
"sira_249": ("Welke metgezel zond de Profeet ﷺ naar Bahrein, die met de schatting ervan terugkeerde?", ["Abu 'Ubayda ibn al-Jarrah", "Bilal", "Anas ibn Malik", "Abu Dharr"], "Abu 'Ubayda ibn al-Jarrah, «de betrouwbare van deze gemeenschap» genoemd, keerde uit Bahrein terug met de schatting ervan."),
"sira_250": ("Welke gebeurtenis markeert het begin van de moslimkalender?", ["De Hidjra van Mekka naar Medina", "De geboorte van de Profeet ﷺ", "De eerste openbaring", "De verovering van Mekka"], "De hidjra-kalender begint met het jaar van de Hidjra, een besluit dat tijdens het kalifaat van 'Umar werd genomen."),
}
